style.css:
@-moz-document domain("starpets.pw") {
/* Basic page setup */
  html, body {
    background-color: #0a0a0f !important;
    color: #e0e0e0 !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
  }

  /* Links and accents */
  a, a:visited {
    color: #66ccff !important;
    text-decoration: none !important;
  }
  a:hover, a:focus {
    color: #99e6ff !important;
  }

  /* Example: navigation / header / footer */
  header, nav, footer, .navbar, .header-container {
    background-color: #11111a !important;
    border-bottom: 1px solid #222233 !important;
  }

  /* Example: for content containers/cards */
  .content, .post, .card, .panel {
    background-color: #12121d !important;
    border: 1px solid #222233 !important;
    border-radius: 4px !important;
    padding: 12px !important;
  }

  /* Example: buttons */
  button, input[type="submit"], .btn {
    background-color: #22223a !important;
    color: #e0e0e0 !important;
    border: 1px solid #66ccff !important;
  }
  button:hover, .btn:hover {
    background-color: #2a2a44 !important;
    border-color: #99e6ff !important;
  }

  /* Example: headings */
  h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
  }

  /* Optionally invert images (if you'd like a stylized look) */
  /* img {
    filter: brightness(0.9) contrast(1.1) !important;
  } */
}
